/// Returns the name stored for `id` in `table`, or `None` when the table has no entry with that id.
/// The first entry with the id wins.
pub fn lookup(table: &[(u8, &'static str)], id: u8) -> Option<&'static str> {
    table.iter().find(|(k, _)| *k == id).map(|(_, v)| *v)
}
